  <div class="container">
    <h1>🎮 人物状态</h1>

    <!-- 世界状态 -->
    <div class="section" id="world-section">
      <div class="section-title">
        <span>🌍 世界状态</span>
        <button class="toggle-btn" onclick="toggleSection('world-content')">+</button>
      </div>
