            <div class="info-label">特殊规则</div>
            <div id="world-special-rule" class="info-value">加载中...</div>
          </div>
        </div>
      </div>
    </div>

    <!-- 叙事者卡片 -->
    <div class="section" id="cards-section">
      <div class="section-title">
        <span>🃏 叙事者卡片</span>
        <button class="toggle-btn" onclick="toggleSection('cards-content')">+</button>
      </div>
      <div class="section-content collapsed" id="cards-content">
        <div id="narrator-cards">
          <div class="empty">暂无卡片</div>
        </div>
      </div>
    </div>

    <!-- 任务列表 -->
    <div class="section" id="tasks-section">
      <div class="section-title">
        <span>📋 任务列表</span>
        <button class="toggle-btn" onclick="toggleSection('tasks-content')">+</button>
      </div>
      <div class="section-content collapsed" id="tasks-content">
        <div id="task-list">
          <div class="empty">暂无任务</div>
        </div>
      </div>
    </div>
  </div>

  <script>
    // ========== 折叠/展开逻辑 ==========
    function toggleSection(contentId) {
      const content = document.getElementById(contentId);
      const btn = content.parentElement.querySelector('.toggle-btn');

      if (content.classList.contains('collapsed')) {
        content.classList.remove('collapsed');
        btn.textContent = '−';
      } else {
        content.classList.add('collapsed');
        btn.textContent = '+';
      }
    }

    // ========== 工具函数 ==========
    function getValue(arr, defaultValue = '') {
      if (Array.isArray(arr) && arr.length > 0) {
        return arr[0] !== undefined ? arr[0] : defaultValue;
      }
      return defaultValue;
    }

    // ========== 状态更新函数 ==========
    function updateWorldState(data) {
      // 世界状态
      const worldTime = getValue(data['世界']?.['时间'], '未知时间');
      const worldLocation = getValue(data['世界']?.['地点'], '未知地点');
      const worldSpecialRule = getValue(data['世界']?.['特殊规则'], '无特殊规则');
      document.getElementById('world-time').textContent = worldTime;
      document.getElementById('world-location').textContent = worldLocation;
      document.getElementById('world-special-rule').textContent = worldSpecialRule;

      // === 叙事者卡片 ===
      const narratorCardsContainer = document.getElementById('narrator-cards');
      const cardsArray = data['叙事者卡片'];
      if (Array.isArray(cardsArray) && cardsArray.length > 0 && typeof cardsArray[0] === 'object') {
        const cardsObj = cardsArray[0];
        const validCards = [];

        for (const [key, card] of Object.entries(cardsObj)) {
          const cardId = getValue(card?.['卡片ID'], '');
          const title = getValue(card?.['卡片名称'], '');
          if (cardId === '' || title === '【未命名卡片】') {
            continue;
          }
          validCards.push({ key, card });
        }

        if (validCards.length > 0) {
          narratorCardsContainer.innerHTML = '';
          validCards.forEach(({ card }) => {
            const name = getValue(card['卡片名称'], '【未命名卡片】');
            const id = getValue(card['卡片ID'], 'N/A');
            const level = getValue(card['卡片等级'], '未知');
            const desc = getValue(card['卡片描述'], '效果未知');
            const quote = getValue(card['卡片引言'], '');

            const cardEl = document.createElement('div');
            cardEl.className = 'card';
            cardEl.innerHTML = `
              <div class="card-title">${name}</div>
              <div><span class="label">卡片ID：</span> ${id}</div>
              <div><span class="label">等级：</span> ${level}</div>
              <div><span class="label">效果：</span> ${desc}</div>
              ${quote ? `<div><span class="label">引言：</span> “${quote}”</div>` : ''}
            `;
            narratorCardsContainer.appendChild(cardEl);
          });
        } else {
          narratorCardsContainer.innerHTML = '<div class="empty">暂无叙事者卡片</div>';
        }
      } else {
        narratorCardsContainer.innerHTML = '<div class="empty">暂无叙事者卡片</div>';
      }

      // === 任务列表 ===
      const taskListContainer = document.getElementById('task-list');
      const tasksArray = data['任务列表'];
      if (Array.isArray(tasksArray) && tasksArray.length > 0 && typeof tasksArray[0] === 'object') {
        const tasksObj = tasksArray[0];
        const validTasks = [];

        for (const [key, task] of Object.entries(tasksObj)) {
          const title = getValue(task?.['标题'], '');
          if (title === '') {
            continue;
          }
          validTasks.push({ key, task });
        }

        if (validTasks.length > 0) {
          taskListContainer.innerHTML = '';
          validTasks.forEach(({ task }) => {
            const title = getValue(task['标题'], '无标题任务');
            const intro = getValue(task['简介'], '暂无描述');
            const goal = getValue(task['目标'], '目标未设定');
            const reward = getValue(task['奖励'], '未知奖励');

            const taskEl = document.createElement('div');
            taskEl.className = 'task';
            taskEl.innerHTML = `
              <div class="task-title">${title}</div>
              <div><span class="label">简介：</span> ${intro}</div>
              <div><span class="label">目标：</span> ${goal}</div>
              <div><span class="label">奖励：</span> ${reward}</div>
            `;
            taskListContainer.appendChild(taskEl);
          });
        } else {
          taskListContainer.innerHTML = '<div class="empty">暂无任务</div>';
        }
      } else {
        taskListContainer.innerHTML = '<div class="empty">暂无任务</div>';
      }
    }
    // ========== 初始化 ==========
    async function initDisplay() {
      try {
        const messages = await getChatMessages(getCurrentMessageId());
        if (!messages || messages.length === 0 || !messages[0].data) {
          throw new Error('消息为空或不含 data');
        }
        const characterData = messages[0].data.stat_data;
        if (!characterData) {
          throw new Error('stat_data 缺失');
        }
        updateWorldState(characterData);
      } catch (error) {
        console.error('状态栏加载出错:', error);
        document.body.innerHTML = `<p style='color:red; padding:20px; text-align:center; background:#222;'>状态栏加载异常: ${error.message}</p>`;
      }
    }

    window.addEventListener('DOMContentLoaded', initDisplay);
  </script>
</body>
</html>
