  // DOM 元素
  const playerNameInput = document.getElementById('playerName');
  const cardSelector = document.getElementById('cardSelector');
  const storySelector = document.getElementById('storySelector');
  const cardModal = document.getElementById('cardModal');
  const storyModal = document.getElementById('storyModal');
  const closeCardModalBtn = document.getElementById('closeCardModal');
  const closeStoryModalBtn = document.getElementById('closeStoryModal');
  const cardList = document.getElementById('cardList');
  const storyList = document.getElementById('storyList');
  const selectedCardDisplay = document.getElementById('selectedCardDisplay');
  const selectedStoryDisplay = document.getElementById('selectedStoryDisplay');
  const sendButton = document.getElementById('sendButton');

  // 当前选中的选项
  let selectedCard = null;
  let selectedStory = null;

  // 渲染叙事者卡片
  function renderCardList() {
    cardList.innerHTML = '';
    NARRATOR_CARDS.forEach(card => {
      const div = document.createElement('div');
      div.className = 'card-item';
      div.innerHTML = `
        <div class="card-title">【${card.name}】</div>
        <div class="card-level">等级：${card.level}</div>
        <div><strong>效果：</strong>${card.effect}</div>
        <div><em>${card.quote}</em></div>
      `;
      div.onclick = () => {
        selectedCard = card;
        selectedCardDisplay.style.display = 'block';
        selectedCardDisplay.innerHTML = `已选择：【${card.name}】 - ${card.quote}`;
        cardModal.style.display = 'none';
      };
      cardList.appendChild(div);
    });
  }

  // 渲染开局故事
  function renderStoryList() {
    storyList.innerHTML = '';
    OPENING_STORIES.forEach(story => {
      const div = document.createElement('div');
      div.className = 'card-item';
      div.innerHTML = `
        <div class="card-title">【${story.name}】</div>
        <div class="card-level">类型：${story.level}</div>
        <div><strong>背景：</strong>${story.effect}</div>
        <div><em>${story.quote}</em></div>
      `;
      div.onclick = () => {
        selectedStory = story;
        selectedStoryDisplay.style.display = 'block';
        selectedStoryDisplay.innerHTML = `已选择：【${story.name}】 - ${story.quote}`;
        storyModal.style.display = 'none';
      };
      storyList.appendChild(div);
    });
  }

  // 事件绑定：叙事者卡片
  cardSelector.addEventListener('click', () => {
    renderCardList();
    cardModal.style.display = 'flex';
  });

  closeCardModalBtn.addEventListener('click', () => {
    cardModal.style.display = 'none';
  });

  // 事件绑定：开局故事
  storySelector.addEventListener('click', () => {
    renderStoryList();
    storyModal.style.display = 'flex';
  });

  closeStoryModalBtn.addEventListener('click', () => {
    storyModal.style.display = 'none';
  });

  // 点击模态框外部关闭
  window.addEventListener('click', (e) => {
    if (e.target === cardModal) cardModal.style.display = 'none';
    if (e.target === storyModal) storyModal.style.display = 'none';
  });

  // 发送按钮逻辑
  sendButton.addEventListener('click', () => {
    const name = playerNameInput.value.trim();
    if (!name) {
      alert('请输入玩家姓名！');
      return;
    }
    if (!selectedStory) {
      alert('请选择一个开局故事！');
      return;
    }
    if (!selectedCard) {
      alert('请选择一张初始叙事者卡片！');
      return;
    }

    const storyHook = `初始叙事者卡片：\n【${selectedCard.name}】\n等级：${selectedCard.level}\n效果：${selectedCard.effect}\n引言：${selectedCard.quote}`;
    const openingHook = `开局故事：\n【${selectedStory.name}】\n类型：${selectedStory.level}\n背景：${selectedStory.effect}\n引言：${selectedStory.quote}`;

    let message = `角色初始信息：\n` +
      `姓名: ${name}\n\n` +
      `${openingHook}\n\n` +
      `${storyHook}\n\n`;
    message += `\n\n(生成开局时，完整叙事者卡片和开局故事的名称与描述，严禁任何修改和省略，将其直接添加到系统中)`;

    if (typeof triggerSlash !== 'undefined') {
      triggerSlash(`/send ${message}`);
      sendButton.textContent = '已发送!';
      setTimeout(() => { sendButton.textContent = '踏上旅程'; }, 2000);
    } else {
      console.log('SillyTavern API未找到。');
      console.log(message);
      alert('未在SillyTavern环境中运行。请在控制台查看生成的数据。');
    }
  });
</script>

</body>
</html>
